+        int start = 0;
+        int end = value.length();
+        while (start < end && isSpaceOrTab(value.charAt(start))) {
+            start++;
+        }
+        while (end > start && isSpaceOrTab(value.charAt(end - 1))) {
+            end--;
+        }
